-- GOLIVE-2 Step 0 · 线上只读计数(以 postgres,rolbypassrls,基表)
SELECT 'PROOF|dict_probes=' || sum(n) FROM (SELECT 'substances'::text t, count(*)*13 n FROM substances UNION ALL SELECT 'battery_chemistries'::text t, count(*)*1 n FROM battery_chemistries UNION ALL SELECT 'material_kinds'::text t, count(*)*1 n FROM material_kinds UNION ALL SELECT 'inbound_safety_states'::text t, count(*)*1 n FROM inbound_safety_states UNION ALL SELECT 'laboratories'::text t, count(*)*1 n FROM laboratories UNION ALL SELECT 'inbound_source_reasons'::text t, count(*)*1 n FROM inbound_source_reasons UNION ALL SELECT 'nea_waste_categories'::text t, count(*)*2 n FROM nea_waste_categories UNION ALL SELECT 'dangerous_goods_codes'::text t, count(*)*1 n FROM dangerous_goods_codes UNION ALL SELECT 'label_templates'::text t, count(*)*1 n FROM label_templates UNION ALL SELECT 'shifts'::text t, count(*)*2 n FROM shifts UNION ALL SELECT 'processing_event_types'::text t, count(*)*1 n FROM processing_event_types UNION ALL SELECT 'cell_constructions'::text t, count(*)*2 n FROM cell_constructions UNION ALL SELECT 'contamination_streams'::text t, count(*)*1 n FROM contamination_streams UNION ALL SELECT 'downtime_causes'::text t, count(*)*1 n FROM downtime_causes UNION ALL SELECT 'incident_kinds'::text t, count(*)*1 n FROM incident_kinds UNION ALL SELECT 'environmental_parameters'::text t, count(*)*1 n FROM environmental_parameters UNION ALL SELECT 'assay_indicators'::text t, count(*)*1 n FROM assay_indicators) s;
SELECT 'PROOF|change_log=' || count(*) || ' txids=' || count(DISTINCT txid) FROM change_log;
